ION", "path": "api/v2/api.go", "references": ["AlertToOpenAPIAlert", "Compile", "Debug", "Error", "Fingerprint", "MatchString", "ModelLabelSetToAPILabelSet", "NewGetAlertGroupsBadRequest", "NewGetAlertGroupsOK", "Sprintf", "WithPayload", "alertFilter", "alertGroups", "append", "func", "getAlertStatus", "groupMutedFunc", "len", "make", "parseFilter", "requestLogger"], "symbol": "getAlertGroupsHandler", "truncated": false}], "selected_ids": ["CU-a11ac3ca3241b405", "CU-ae9f6b7d55fea922", "CU-2224c444e2402982", "CU-f7fcaf75f9686180", "CU-HELPER-c76cc3560e30e77d", "CU-78fb92ebca3e38c0", "CU-HELPER-2605c1d6fe69909a", "CU-46f93d75aac817de", "CU-HELPER-993996d987a4f64e", "CU-HELPER-13a7192116182822", "CU-HELPER-62b5e84fb39809d4", "CU-bb268abc9d83776d"]}, "evidence_catalog": [{"content_digest": "05f3654077513fca40abde4311a1059da37ab428064f49018eeefd5d7d954e92", "excerpt": "func (d *Dispatcher) Groups(routeFilter func(*Route) bool, alertFilter func(*types.Alert, time.Time) bool) (AlertGroups, map[model.Fingerprint][]string) {
	groups := AlertGroups{}

	d.mtx.RLock()
	defer d.mtx.RUnlock()

	// Keep a list of receivers for an alert to prevent checking each alert
	// again against all routes. The alert has already matched against this
	// route on ingestion.
	receivers := map[model.Fingerprint][]string{}

	now := time.Now()
	for route, ags := range d.aggrGroupsPerRoute {
		if !routeFilter(route) {
			continue
		}

		for _, ag := range ags {
			receiver := route.RouteOpts.Receiver
			alertGroup := &AlertGroup{
				Labels:   ag.labels,
				Receiver: receiver,
				GroupKey: ag.GroupKey(),
				RouteID:  ag.routeID,
			}

			alerts := ag.alerts.List()
			filteredAlerts := make([]*types.Alert, 0, len(alerts))
			for _, a := range alerts {
				if !alertFilter(a, now) {
					continue
				}

				fp := a.Fingerprint()
				if r, ok := receivers[fp]; ok {
					// Receivers slice already exists. Add
					// the current receiver to the slice.
					receivers[fp] = append(r, receiver)
				} else {
					// First time we've seen this alert fingerprint.
					// Initialize a new receivers slice.
					receivers[fp] = []string{receiver}
				}

				filteredAlerts = append(filteredAlerts, a)
			}
			if len(filteredAlerts) == 0 {
				continue
			}
			alertGroup.Alerts = filteredAlerts

			groups = append(groups, alertGroup)
		}
	}
	sort.Sort(groups)
	for i := range groups {
		sort.Sort(groups[i].Alerts)
	}
	for i := range receivers {
		sort.Strings(receivers[i])
	}

	return groups, receivers
}
